head.script:
scwin.screenId = "jlddst00100";

///////// 1. 변수 및 선언 영역 /////////

scwin.outsvcno = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
// 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
/**
 * @method
 * @name scwin.init_ctxDefaults
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_ctxDefaults = function () {
    const cds = {"outsvcno":"true"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_kosreq", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "kosreq" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("kosreq")) === 'y'); } }, { id: "if_kosreq_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "kosreq" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("kosreq")) !== 'y'); } }, { id: "if_outsvcno", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.outsvcno !== "undefined" && scwin.outsvcno !== null ? scwin.outsvcno : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "outsvcno" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("outsvcno")) !== true); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_kosreq", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("kosreq")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        let searchCorpName = $c.util.getComponent('AKCKwd').getValue(); if (searchCorpName == null) { searchCorpName = ''; }
        if (searchCorpName !== "") {
            Promise.resolve($c.win.openPopup('/jldfil00033/jldfil00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    }
    if ($c.util.getComponent('ipt_kosreq').getValue() === "y") {
        (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(KOSCOM)");
    }
    scwin.fnBookmark();
    scwin.btn_pd_1m_onclick();
    setTimeout(scwin.fnInit, 100);
    /* sdd-asis-lifecycle:end */

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst00100.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.fnBookmarkSearch = fnBookmarkSearch;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jlddst00100.onpageload' });
    }
};


