    if (val === "") {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        var val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
    } else {
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", val);
        await scwin.fnInit();
    }
    /* sdd-asis-lifecycle:end */
};


