/**
 * @method
 * @name scwin.fnPeriodValidation
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnPeriodValidation = async function () {
    /* sdd-asis-lifecycle:begin fnPeriodValidation — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fromDate = $c.util.getComponent('cal_fromDate').getValue();
    const toDate = $c.util.getComponent('cal_toDate').getValue();
    let searchCorpName = $c.util.getComponent('AKCKwd').getValue(); if (searchCorpName == null) { searchCorpName = ''; }
    let reportNmTemp = $c.util.getComponent('ipt_reportNmTemp').getValue(); if (reportNmTemp == null) { reportNmTemp = ''; }
    if (searchCorpName === "" && ($c.util.getComponent('ipt_allRepIsuSrtCd').getValue() == null ? '' : String($c.util.getComponent('ipt_allRepIsuSrtCd').getValue())) === '' && reportNmTemp === "") {
        if ($c.date.addYear(fromDate, 1) < $c.date.addYear(toDate, 0)) {
            await $c.win.alert("기간이 1년을 넘을 경우 회사명 또는 보고서명을 입력해 주세요.");
            return false;
        } else {
            return true;
        }
    } else {
        return true;
    }
    /* sdd-asis-lifecycle:end */
};


